    items.push(MenuItem::separator());

    // Spatial section
    items.push(MenuItem::new("spatial-header", "Spatial").disabled(true));
    items.push(MenuItem::new("plugin-upmixer", "Upmixer"));
    items.push(MenuItem::new("plugin-aae", "AAE Reverb"));
